mapper.select:
SELECT COALESCE(SUM(total_tokens), 0)
FROM ai_health_reports
WHERE created_at >= #{startTime}
  AND created_at < #{endTime}

mapper.delete:
DELETE FROM ai_health_reports
WHERE created_at < #{cutoffTime}
ORDER BY id
LIMIT #{batchSize}

mapper.select:
SELECT r.server_id AS server_id, s.name AS server_name,
       COUNT(*) AS alert_count,
       COALESCE(SUM(CASE WHEN r.level = 'critical' THEN 1 ELSE 0 END), 0) AS critical_count
FROM alert_records r
JOIN servers s ON s.id = r.server_id AND s.deleted = 0
WHERE r.triggered_at >= #{startTime}
  AND r.triggered_at < #{endTime}
GROUP BY r.server_id, s.name
ORDER BY alert_count DESC, r.server_id ASC
LIMIT #{limit}
